// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import 'forge-std/Test.sol';
import '../../src/deployments/interfaces/IMarketReportTypes.sol';

import {AugustusRegistryMock} from '../mocks/AugustusRegistryMock.sol';
