      address paraswapWithdrawSwapOwner = Ownable(report.paraSwapWithdrawSwapAdapter).owner();
      assertEq(
        paraswapRepayAdapterOwner,
        roles.poolAdmin,
        'roles.poolAdmin must be paraswap repay owner'
      );
      assertEq(
        paraswapSwapAdapterOwner,
