    assets[0] = tokenList.weth;
    assets[1] = tokenList.wbtc;

    contracts.poolProxy.mintToTreasury(assets);

    vm.snapshotGasLastCall('Pool.Operations', 'mintToTreasury: two assets with non zero amount');
