    // Perform action
    vm.prank(poolAdmin);
    contracts.poolConfiguratorProxy.initReserves(input);
    (, , , , , , bool borrowingEnabledDefault, , , ) = contracts
      .protocolDataProvider
      .getReserveConfigurationData(input[0].underlyingAsset);
    assertEq(borrowingEnabledDefault, false);

