      delegatee: bob,
      value: amount,
      nonce: 0,
      deadline: deadline
    });

    bytes32 digest = EIP712SigUtils.getCreditDelegationTypedDataHash(
      delegation,
      bytes(variableDebtToken.name()),
      bytes('1'),
      address(variableDebtToken)
    );

