  function test_mint_shouldRevertIfSenderIsNotApproved() external {
    address sender = address(0x1);
    address owner = address(0x2);
    uint256 amount = 100;
    vm.expectRevert(
      abi.encodeWithSelector(
        ICreditDelegationToken.InsufficientBorrowAllowance.selector,
